$root = (Resolve-Path "$PSScriptRoot\..\..").Path; $legacyData = Join-Path $env:USERPROFILE '.avatarkit'; if (-not $env:AVATARKIT_HOME -or $env:AVATARKIT_HOME -eq $legacyData) { $env:AVATARKIT_HOME = Join-Path $root '.avatarkit' }; $python = Join-Path $env:AVATARKIT_HOME 'environments\backend\Scripts\python.exe'; if (-not (Test-Path $python)) { throw 'Run setup.ps1 first.' }; & $python -c "from app.main import diagnostics; import json; print(json.dumps(diagnostics(), indent=2))" --% 2>$null
